/*!40000 ALTER TABLE `articles` DISABLE KEYS */;
INSERT INTO `articles` VALUES ('AR-001','{\"body\": \"Memilih metode pembayaran rumah yang tepat sama pentingnya dengan memilih lokasi dan tipe hunian. Di LinyJaya Development, calon pembeli diberikan kebebasan memilih tiga metode pembayaran resmi yang transparan:\\n\\n1. Cash Keras (Tunai Keras): Cocok bagi Anda yang memiliki dana likuid dan ingin mendapatkan keuntungan finansial maksimal. Anda berhak mendapatkan diskon langsung 5%, bebas seluruh biaya legalitas (BPHTB, Notaris, Balik Nama SHM), serta prioritas serah terima unit.\\n\\n2. Cash Lunak / Bertahap ke Developer: Solusi terbaik jika Anda ingin mencicil tanpa melalui proses bank. Skema ini mengenakan bunga 0% flat langsung ke LinyJaya, tanpa BI Checking / SLIK OJK, dengan pilihan tenor 12, 24, hingga 36 bulan. Syaratnya cukup KTP dan NPWP.\\n\\n3. KPR Bank (Syariah & Konvensional): Pilihan tepat untuk cicilan ringan jangka panjang (10 hingga 25 tahun). Didukung oleh bank mitra terkemuka seperti BSI, BTN, Mandiri, BCA, dan BNI, dengan program promo DP mulai 10% serta subsidi biaya KPR hingga Rp 15 Juta. Tim Property Advisor LinyJaya siap mendampingi pemberkasan Anda hingga akad kredit.\", \"date\": \"2026-11-03\", \"image\": \"interior\", \"title\": \"Panduan Memilih Cara Bayar: Cash Keras, Cash Bertahap, atau KPR?\", \"summary\": \"Ketahui keunggulan Cash Keras dengan diskon spesial, kemudahan Cash Bertahap bunga 0%, dan keringanan KPR Bank.\", \"category\": \"Panduan Finansial\"}','2026-11-09 06:37:12','2026-11-09 06:37:12'),('AR-002','{\"body\": \"Pembangunan dimulai dari persiapan lahan dan pengukuran, kemudian pondasi, struktur, dinding, atap, serta instalasi. Setiap tahap membutuhkan pemeriksaan sebelum pekerjaan berikutnya dimulai.\\n\\nFinishing mencakup lantai, cat, perlengkapan, dan pemeriksaan akhir. Persentase progres merupakan ringkasan pekerjaan, bukan pengganti laporan pemeriksaan mutu.\\n\\nDokumentasi dan laporan progres membantu Anda memahami perkembangan rumah dalam satu rangkaian tahapan. Periksa pembaruan jadwal secara berkala dan diskusikan kebutuhan Anda dengan tim proyek.\", \"date\": \"2026-10-28\", \"image\": \"construction\", \"title\": \"Mengenal tahapan pembangunan rumah Anda\", \"summary\": \"Dari persiapan lahan hingga finishing: pahami apa yang dikerjakan di setiap tahap.\", \"category\": \"Konstruksi\"}','2026-11-09 06:37:12','2026-11-09 06:37:12'),('AR-003','{\"body\": \"Bukaan yang direncanakan dengan baik membantu cahaya alami masuk dan udara bersirkulasi. Perhatikan orientasi bangunan, kedalaman ruang, dan peneduh.\\n\\nTaman kecil, jendela yang saling berhadapan, dan material berwarna terang dapat memperbaiki pengalaman ruang. Diskusikan perubahan desain dengan tim teknik sebelum pelaksanaan.\", \"date\": \"2026-10-20\", \"image\": \"house-2\", \"title\": \"Cahaya alami, detail kecil yang mengubah suasana\", \"summary\": \"Ruang yang sehat dimulai dari sirkulasi udara dan pencahayaan yang direncanakan.\", \"category\": \"Inspirasi hunian\"}','2026-11-09 06:37:12','2026-11-09 06:37:12');
/*!40000 ALTER TABLE `articles` ENABLE KEYS */;

